import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong(), root = (int) nextLong() - 1;
        int[] eu = new int[m], ev = new int[m], deg = new int[n + 1];
        for (int i = 0; i < m; i++) {
            eu[i] = (int) nextLong() - 1;
            ev[i] = (int) nextLong() - 1;
            deg[eu[i]]++;
            deg[ev[i]]++;
        }
        // Compressed adjacency lists.
        int[] start = new int[n + 1];
        for (int i = 0; i < n; i++) start[i + 1] = start[i] + deg[i];
        int[] fill = Arrays.copyOf(start, n), adj = new int[2 * m];
        for (int i = 0; i < m; i++) {
            adj[fill[eu[i]]++] = ev[i];
            adj[fill[ev[i]]++] = eu[i];
        }
        int[] d = new int[n];
        Arrays.fill(d, -1);
        d[root] = 0;
        int[] queue = new int[n];
        int head = 0, tail = 0;
        queue[tail++] = root;
        while (head < tail) {
            int u = queue[head++];
            for (int e = start[u]; e < start[u + 1]; e++)
                if (d[adj[e]] < 0) {
                    d[adj[e]] = d[u] + 1;
                    queue[tail++] = adj[e];
                }
        }
        // Reachable cities except the factory, ordered by (distance, id).
        long[] order = new long[n];
        int count = 0;
        for (int i = 0; i < n; i++)
            if (i != root && d[i] >= 0) order[count++] = ((long) d[i] << 20) | i;
        Arrays.sort(order, 0, count);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            if (i > 0) sb.append(' ');
            sb.append((order[i] & ((1 << 20) - 1)) + 1);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m, root := int(nextInt()), int(nextInt()), int(nextInt())-1
	g := make([][]int, n)
	for i := 0; i < m; i++ {
		u, v := int(nextInt())-1, int(nextInt())-1
		g[u] = append(g[u], v)
		g[v] = append(g[v], u)
	}
	d := make([]int, n)
	for i := range d {
		d[i] = -1
	}
	d[root] = 0
	queue := []int{root}
	for head := 0; head < len(queue); head++ {
		u := queue[head]
		for _, v := range g[u] {
			if d[v] < 0 {
				d[v] = d[u] + 1
				queue = append(queue, v)
			}
		}
	}
	// Reachable cities except the factory, ordered by (distance, id).
	order := []int{}
	for i := 0; i < n; i++ {
		if i != root && d[i] >= 0 {
			order = append(order, i)
		}
	}
	slices.SortFunc(order, func(a, b int) int {
		if d[a] != d[b] {
			return d[a] - d[b]
		}
		return a - b
	})
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, c := range order {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(c + 1))
	}
	w.WriteByte('\n')
}
